        b.addGroup(translationX = -x, translationY = -y)
        for ((d, color) in paths) {
            b.addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(color ?: Color.Black), pathFillType = PathFillType.EvenOdd)
